223	export default function vercelAdapter({
224		webAnalytics,
225		includeFiles: _includeFiles = [],
226		excludeFiles: _excludeFiles = [],
227		imageService,
228		imagesConfig,
229		devImageService = 'sharp',
230		middlewareMode,
231		edgeMiddleware,
232		maxDuration,
233		isr = false,
234		skewProtection = process.env.VERCEL_SKEW_PROTECTION_ENABLED === '1',
235		staticHeaders = false,
236	}: VercelServerlessConfig = {}): AstroIntegration {
237		// Resolve middleware mode with backward compatibility
238		const resolvedMiddlewareMode = middlewareMode ?? (edgeMiddleware ? 'edge' : 'classic');
239	
240		if (maxDuration) {
241			if (typeof maxDuration !== 'number') {
242				throw new TypeError(`maxDuration must be a number`, {
243					cause: maxDuration,
244				});
