278						);
279					}
280	
281					staticDir = new URL('./.vercel/output/static', config.root);
282					updateConfig({
283						build: {
284							format: 'directory',
285							redirects: false,
286						},
287						integrations: [
288							{
289								name: 'astro:copy-vercel-output',
290								hooks: {
