402						});
403	
404						mkdirSync(new URL('./.vercel/output/server/', _config.root));
405	
406						if (_buildOutput !== 'static') {
407							cpSync(_config.build.server, new URL('./.vercel/output/_functions/', _config.root), {
408								recursive: true,
409							});
410						}
411					}
412	
413					const routeDefinitions: Array<{
414						src: string;
415						dest: string;
416						middlewarePath?: string;
417					}> = [];
418	
419					if (_buildOutput === 'server') {
420						// Merge any includes from `vite.assetsInclude
421						if (_config.vite.assetsInclude) {
422							const mergeGlobbedIncludes = (globPattern: unknown) => {
423								if (typeof globPattern === 'string') {
424									const entries = globSync(globPattern).map((p) => pathToFileURL(p));
425									extraFilesToInclude.push(...entries);
426								} else if (Array.isArray(globPattern)) {
427									for (const pattern of globPattern) {
428										mergeGlobbedIncludes(pattern);
429									}
430								}
431							};
432	
433							mergeGlobbedIncludes(_config.vite.assetsInclude);
434						}
435	
436						const includeFiles = _includeFiles
437							.map((file) => new URL(file, _config.root))
438							.concat(extraFilesToInclude);
439						const excludeFiles = _excludeFiles.map((file) => new URL(file, _config.root));
440	
441						const builder = new VercelBuilder(
442							_config,
443							excludeFiles,
444							includeFiles,
445							logger,
446							outDir,
447							maxDuration,
448						);
449	
450						const entryFile = new URL(_serverEntry, _buildTempFolder);
451						if (isr) {
452							const isrConfig = typeof isr === 'object' ? isr : {};
453							await builder.buildServerlessFolder(entryFile, NODE_PATH, _config.root);
454							if (isrConfig.exclude?.length) {
