319						),
320					});
321				},
322				'astro:routes:resolved': (params) => {
323					routes = params.routes;
324				},
325				'astro:config:done': ({ setAdapter, config, logger, buildOutput }) => {
326					_buildOutput = buildOutput;
327	
328					if (_buildOutput === 'server') {
329						if (maxDuration && maxDuration > 900) {
330							logger.warn(
331								`maxDuration is set to ${maxDuration} seconds, which is longer than the maximum allowed duration of 900 seconds.`,
332							);
333							logger.warn(
334								`Please make sure that your plan allows for this duration. See https://vercel.com/docs/functions/serverless-functions/runtimes#maxduration for more information.`,
335							);
336						}
337						const vercelConfigPath = new URL('vercel.json', config.root);
338						if (
339							config.trailingSlash &&
340							config.trailingSlash !== 'ignore' &&
341							existsSync(vercelConfigPath)
342						) {
343							try {
344								const vercelConfig = JSON.parse(readFileSync(vercelConfigPath, 'utf-8'));
345								if (
346									(vercelConfig.trailingSlash === true && config.trailingSlash === 'never') ||
347									(vercelConfig.trailingSlash === false && config.trailingSlash === 'always')
348								) {
349									logger.error(
350										`
351		Your "vercel.json" \`trailingSlash\` configuration (set to \`${vercelConfig.trailingSlash}\`) will conflict with your Astro \`trailingSlash\` configuration (set to \`${JSON.stringify(config.trailingSlash)}\`).
352		This would cause infinite redirects or duplicate content issues. 
353		Please remove the \`trailingSlash\` configuration from your \`vercel.json\` file or Astro config.
354	`,
355									);
356								}
357							} catch (_err) {
358								logger.warn(`Your "vercel.json" config is not a valid json file.`);
359							}
360						}
361						setAdapter(
362							getAdapter({
363								buildOutput: _buildOutput,
364								middlewareMode: resolvedMiddlewareMode,
365								skewProtection,
366								staticHeaders: staticHeaders,
367							}),
368						);
369					} else {
370						setAdapter(
371							getAdapter({
372								middlewareMode: resolvedMiddlewareMode,
373								skewProtection,
374								buildOutput: _buildOutput,
375								staticHeaders: staticHeaders,
376							}),
377						);
378					}
379					_config = config;
380					_buildTempFolder = config.build.server;
381					_serverEntry = config.build.serverEntry;
382				},
383				'astro:build:start': async () => {
384					// Ensure to have `.vercel/output` empty.
385					await emptyDir(new URL('./.vercel/output/', _config.root));
386				},
387				'astro:build:ssr': async ({ middlewareEntryPoint }) => {
388					_middlewareEntryPoint = middlewareEntryPoint;
389				},
390	
391				'astro:build:generated': ({ routeToHeaders }) => {
392					_routeToHeaders = routeToHeaders;
393				},
394				'astro:build:done': async ({ logger }: HookParameters<'astro:build:done'>) => {
395					const outDir = new URL('./.vercel/output/', _config.root);
396					if (staticDir) {
397						if (existsSync(staticDir)) {
398							emptyDir(staticDir);
399						}
400						mkdirSync(new URL('./.vercel/output/static/', _config.root), {
401							recursive: true,
402						});
403	
404						mkdirSync(new URL('./.vercel/output/server/', _config.root));
405	
406						if (_buildOutput !== 'static') {
407							cpSync(_config.build.server, new URL('./.vercel/output/_functions/', _config.root), {
408								recursive: true,
409							});
410						}
411					}
412	
413					const routeDefinitions: Array<{
414						src: string;
415						dest: string;
416						middlewarePath?: string;
417					}> = [];
418	
419					if (_buildOutput === 'server') {
420						// Merge any includes from `vite.assetsInclude
421						if (_config.vite.assetsInclude) {
422							const mergeGlobbedIncludes = (globPattern: unknown) => {
423								if (typeof globPattern === 'string') {
424									const entries = globSync(globPattern).map((p) => pathToFileURL(p));
425									extraFilesToInclude.push(...entries);
426								} else if (Array.isArray(globPattern)) {
427									for (const pattern of globPattern) {
428										mergeGlobbedIncludes(pattern);
429									}
430								}
431							};
432	
433							mergeGlobbedIncludes(_config.vite.assetsInclude);
434						}
435	
436						const includeFiles = _includeFiles
437							.map((file) => new URL(file, _config.root))
438							.concat(extraFilesToInclude);
439						const excludeFiles = _excludeFiles.map((file) => new URL(file, _config.root));
440	
441						const builder = new VercelBuilder(
442							_config,
443							excludeFiles,
444							includeFiles,
445							logger,
446							outDir,
447							maxDuration,
448						);
449	
450						const entryFile = new URL(_serverEntry, _buildTempFolder);
451						if (isr) {
452							const isrConfig = typeof isr === 'object' ? isr : {};
453							await builder.buildServerlessFolder(entryFile, NODE_PATH, _config.root);
454							if (isrConfig.exclude?.length) {
455								const expandedExclusions = isrConfig.exclude.flatMap((exclusion) => {
456									if (exclusion instanceof RegExp) {
457										return routes
458											.filter((route) => exclusion.test(route.pattern))
459											.map((route) => route.pattern);
460									}
461	
462									return [exclusion];
463								});
464	
465								const dest = _middlewareEntryPoint ? MIDDLEWARE_PATH : NODE_PATH;
466								for (const route of expandedExclusions) {
467									// vercel interprets src as a regex pattern, so we need to escape it
468									routeDefinitions.push({
469										src: escapeRegex(route),
470										dest,
471									});
472								}
473							}
474							await builder.buildISRFolder(entryFile, '_isr', isrConfig, _config.root);
475							for (const route of routes) {
476								// Do not create _isr route entries for excluded routes
477								const excludeRouteFromIsr = isrConfig.exclude?.some((exclusion) => {
478									if (exclusion instanceof RegExp) {
479										return exclusion.test(route.pattern);
480									}
481	
482									return exclusion === route.pattern;
483								});
484	
485								if (!excludeRouteFromIsr) {
486									const src = route.patternRegex.source;
487									const dest =
488										src.startsWith('^\\/_image') || src.startsWith('^\\/_server-islands')
489											? NODE_PATH
490											: ISR_PATH;
491									if (!route.isPrerendered)
492										routeDefinitions.push({
493											src,
494											dest,
495										});
496								}
497							}
498						} else {
499							await builder.buildServerlessFolder(entryFile, NODE_PATH, _config.root);
500							const dest = _middlewareEntryPoint ? MIDDLEWARE_PATH : NODE_PATH;
501							for (const route of routes) {
502								if (!route.isPrerendered)
503									routeDefinitions.push({
504										src: route.patternRegex.source,
505										dest,
506									});
507							}
508						}
509	
510						if (_middlewareEntryPoint) {
511							await builder.buildMiddlewareFolder(
512								_middlewareEntryPoint,
513								MIDDLEWARE_PATH,
514								middlewareSecret,
515							);
516						}
517					}
518					const fourOhFourRoute = routes.find((route) => route.pathname === '/404');
519					const vercelConfigJson = new URL('./.vercel/output/config.json', _config.root);
520					const finalRoutes: Route[] = [
521						{
522							src: `^/${_config.build.assets}/(.*)$`,
523							headers: {
524								'cache-control': 'public, max-age=31536000, immutable',
525							},
526							continue: true,
527						},
528					];
529					if (_buildOutput === 'server') {
530						finalRoutes.push(...routeDefinitions);
531					}
532	
533					if (fourOhFourRoute) {
534						if (_buildOutput === 'server') {
535							finalRoutes.push({
536								src: '/.*',
537								dest: fourOhFourRoute.isPrerendered
538									? '/404.html'
539									: _middlewareEntryPoint
540										? MIDDLEWARE_PATH
541										: NODE_PATH,
542								status: 404,
543							});
544						} else {
545							finalRoutes.push({
546								src: '/.*',
547								dest: '/404.html',
548								status: 404,
549							});
550						}
551					}
552					// The Vercel `trailingSlash` option
553					let trailingSlash: boolean | undefined;
554					// Vercel's `trailingSlash` option maps to Astro's like so:
555					// - `true` -> `"always"`
556					// - `false` -> `"never"`
557					// - `undefined` -> `"ignore"`
558					// If config is set to "ignore", we leave it as undefined.
559					if (_config.trailingSlash && _config.trailingSlash !== 'ignore') {
560						// Otherwise, map it accordingly.
561						trailingSlash = _config.trailingSlash === 'always';
562					}
563	
564					const { routes: redirects = [], error } = getTransformedRoutes({
565						trailingSlash,
566						rewrites: [],
567						redirects: getRedirects(routes, _config),
568						headers: [],
569					});
570					if (error) {
571						throw new AstroError(
572							`Error generating redirects: ${error.message}`,
573							error.link ? `${error.action ?? 'More info'}: ${error.link}` : undefined,
574						);
575					}
576	
577					let images: VercelImageConfig | undefined;
578					if (imagesConfig) {
579						images = {
580							...imagesConfig,
581							domains:
582								imagesConfig.domains || _config.image.domains
583									? [...(imagesConfig.domains ?? []), ...(_config.image.domains ?? [])]
584									: undefined,
585							remotePatterns: [...(imagesConfig.remotePatterns ?? [])],
586						};
587						const remotePatterns = _config.image.remotePatterns;
588						for (const pattern of remotePatterns) {
589							if (isAcceptedPattern(pattern)) {
590								images.remotePatterns?.push(pattern);
591							}
592						}
593					} else if (imageService) {
594						images = getDefaultImageConfig(_config.image);
595					}
596	
597					const normalized = normalizeRoutes([...(redirects ?? []), ...finalRoutes]);
598					if (normalized.error) {
599						throw new AstroError(
600							`Error generating routes: ${normalized.error.message}`,
601							normalized.error.link
602								? `${normalized.error.action ?? 'More info'}: ${normalized.error.link}`
603								: undefined,
604						);
605					}
606	
607					if (_routeToHeaders && _routeToHeaders.size > 0) {
608						if (!normalized.routes) {
609							normalized.routes = [];
610						}
611						if (staticHeaders) {
612							const routesWithConfigHeaders = createRoutesWithStaticHeaders(_routeToHeaders, _config);
613							const fileSystemRouteIndex = normalized.routes.findIndex(
614								(r) => 'handle' in r && r.handle === 'filesystem',
615							);
616							normalized.routes.splice(fileSystemRouteIndex, 0, ...routesWithConfigHeaders);
617						}
618					}
619	
620					// Output configuration
621					// https://vercel.com/docs/build-output-api/v3#build-output-configuration
622					await writeJson(vercelConfigJson, {
623						version: 3,
624						routes: normalized.routes,
625						images,
626					});
627	
628					// Remove temporary folder
629					if (_buildOutput === 'server') {
630						await removeDir(_buildTempFolder);
631					}
632				},
633			},
634		};
635	}
636	
637	function isAcceptedPattern(pattern: any): pattern is RemotePattern {
638		if (pattern == null) {
639			return false;
640		}
641		if (!pattern.hostname) {
642			return false;
643		}
644		if (pattern.protocol && (pattern.protocol !== 'http' || pattern.protocol !== 'https')) {
645			return false;
646		}
647		return true;
648	}
649	
650	type Runtime = `nodejs${string}.x`;
651	
652	class VercelBuilder {
653		readonly NTF_CACHE = {};
654	
655		constructor(
656			readonly config: AstroConfig,
657			readonly excludeFiles: URL[],
658			readonly includeFiles: URL[],
659			readonly logger: AstroIntegrationLogger,
660			readonly outDir: URL,
661			readonly maxDuration?: number,
662			readonly runtime = getRuntime(process, logger),
663		) {}
664	
665		async buildServerlessFolder(entry: URL, functionName: string, root: URL) {
666			const { includeFiles, excludeFiles, logger, NTF_CACHE, runtime, maxDuration } = this;
667			// .vercel/output/functions/<name>.func/
668			const functionFolder = new URL(`./functions/${functionName}.func/`, this.outDir);
669			const packageJson = new URL(`./functions/${functionName}.func/package.json`, this.outDir);
670			const vcConfig = new URL(`./functions/${functionName}.func/.vc-config.json`, this.outDir);
671	
672			// Copy necessary files (e.g. node_modules/)
673			const { handler } = await copyDependenciesToFunction(
674				{
675					entry,
676					outDir: functionFolder,
677					includeFiles,
678					excludeFiles,
679					logger,
680					root,
681				},
682				NTF_CACHE,
683			);
684	
685			// Enable ESM
686			// https://aws.amazon.com/blogs/compute/using-node-js-es-modules-and-top-level-await-in-aws-lambda/
687			await writeJson(packageJson, {
688				type: 'module',
689			});
690	
691			// Serverless function config
692			// https://vercel.com/docs/build-output-api/v3#vercel-primitives/serverless-functions/configuration
693			await writeJson(vcConfig, {
694				runtime,
695				handler: handler.replaceAll('\\', '/'),
696				launcherType: 'Nodejs',
697				maxDuration,
698				supportsResponseStreaming: true,
699			});
700		}
701	
702		async buildISRFolder(entry: URL, functionName: string, isr: VercelISRConfig, root: URL) {
703			await this.buildServerlessFolder(entry, functionName, root);
704			const prerenderConfig = new URL(
705				`./functions/${functionName}.prerender-config.json`,
706				this.outDir,
707			);
708			// https://vercel.com/docs/build-output-api/v3/primitives#prerender-configuration-file
709			await writeJson(prerenderConfig, {
710				expiration: isr.expiration ?? false,
711				bypassToken: isr.bypassToken,
712				allowQuery: [ASTRO_PATH_PARAM],
713				passQuery: true,
714			});
715		}
716	
717		async buildMiddlewareFolder(entry: URL, functionName: string, middlewareSecret: string) {
718			const functionFolder = new URL(`./functions/${functionName}.func/`, this.outDir);
719	
720			await generateEdgeMiddleware(
721				entry,
722				this.config.root,
723				new URL(VERCEL_EDGE_MIDDLEWARE_FILE, this.config.srcDir),
724				new URL('./middleware.mjs', functionFolder),
725				middlewareSecret,
726				this.logger,
727			);
728	
729			await writeJson(new URL(`./.vc-config.json`, functionFolder), {
730				runtime: 'edge',
731				entrypoint: 'middleware.mjs',
732			});
733		}
734	}
735	
736	function getRuntime(process: NodeJS.Process, logger: AstroIntegrationLogger): Runtime {
737		const version = process.version.slice(1); // 'v18.19.0' --> '18.19.0'
738		const major = version.split('.')[0]; // '18.19.0' --> '18'
739		const support = SUPPORTED_NODE_VERSIONS[major];
740		if (support === undefined) {
741			logger.warn(
742				`\n` +
743					`\tThe local Node.js version (${major}) is not supported by Vercel Serverless Functions.\n` +
744					`\tYour project will use Node.js 24 as the runtime instead.\n` +
745					`\tConsider switching your local version to 24.\n`,
746			);
747			return 'nodejs24.x';
748		}
749		if (support.status === 'default' || support.status === 'available') {
750			return `nodejs${major}.x`;
751		}
752		if (support.status === 'retiring') {
753			if (support.warnDate && new Date() >= support.warnDate) {
754				logger.warn(
755					`Your project is being built for Node.js ${major} as the runtime, which is retiring by ${support.removal}.`,
756				);
757			}
758			return `nodejs${major}.x`;
759		}
760		if (support.status === 'beta') {
761			logger.warn(
762				`Your project is being built for Node.js ${major} as the runtime, which is currently in beta for Vercel Serverless Functions.`,
763			);
764			return `nodejs${major}.x`;
765		}
766		if (support.status === 'deprecated') {
767			logger.warn(
768				`\n` +
769					`\tYour project is being built for Node.js ${major} as the runtime.\n` +
770					`\tThis version is deprecated by Vercel Serverless Functions.\n` +
771					`\tConsider upgrading your local version to 24.\n`,
772			);
773			return `nodejs${major}.x`;
774		}
775		return 'nodejs24.x';
776	}
777	
778	function createRoutesWithStaticHeaders(
779		staticHeaders: RouteToHeaders,
780		config: AstroConfig,
781	): RouteWithSrc[] {
782		const vercelHeaders: RouteWithSrc[] = [];
783		for (const [pathname, { headers }] of staticHeaders.entries()) {
784			if (config.security.csp) {
785				const csp = headers.get('Content-Security-Policy');
786	
787				if (csp) {
788					const _headers = {
789						'content-security-policy': csp,
790					};
791					vercelHeaders.push({
792						src: pathname,
793						headers: _headers,
794					});
795				}
796			}
797		}
798	
799		return vercelHeaders;
800	}
